CREATE OR REPLACE FUNCTION public.admin_prepare_transaction_case_refund(p_case_id uuid, p_notes text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid:=auth.uid();
  case_row record;
begin
  if actor is null or not private.is_admin() then raise exception 'Administrator access required.'; end if;

  select c.id,c.case_type,c.status,c.previous_fulfilment_status,c.provider_dispute_id
  into case_row
  from public.transaction_cases c
  where c.id=p_case_id
  for update;

  if case_row.id is null then raise exception 'Case not found.'; end if;
  if case_row.provider_dispute_id is not null then
    raise exception 'Payment-provider disputes must be resolved by the provider outcome.';
  end if;
  if case_row.case_type='return' and case_row.status<>'returned' then
    raise exception 'The returned item must be confirmed received before the standard refund path.';
  end if;
  if case_row.case_type='dispute' and case_row.status not in ('open','seller_response','under_review') then
    raise exception 'This dispute is not available for refund review.';
  end if;
  if case_row.case_type='cancellation' and (
    case_row.status not in ('open','seller_response','under_review')
    or case_row.previous_fulfilment_status not in ('paid','preparing','ready_for_collection')
  ) then
    raise exception 'This cancellation is not available for refund review.';
  end if;

  update public.transaction_cases
  set status='under_review',resolution_notes=nullif(left(btrim(coalesce(p_notes,'')),2000),''),resolved_by=actor
  where id=p_case_id;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_reject_transaction_case(p_case_id uuid, p_notes text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid:=auth.uid();
  case_row record;
begin
  if actor is null or not private.is_admin() then raise exception 'Administrator access required.'; end if;

  select c.*,oi.order_id,oi.release_eligible_at,oi.funds_released_at,o.buyer_id,s.owner_id
  into case_row
  from public.transaction_cases c
  join public.order_items oi on oi.id=c.order_item_id
  join public.orders o on o.id=oi.order_id
  join public.sellers s on s.id=oi.seller_id
  where c.id=p_case_id
  for update of c;

  if case_row.id is null then raise exception 'Case not found.'; end if;
  if case_row.provider_dispute_id is not null then
    raise exception 'Payment-provider disputes can only be closed by the provider outcome.';
  end if;
  if case_row.status not in ('open','seller_response','under_review') then raise exception 'Case is already closed.'; end if;

  update public.transaction_cases
  set status='rejected',resolution='no_refund',resolution_notes=nullif(left(btrim(coalesce(p_notes,'')),2000),''),
      resolved_by=actor,resolved_at=now()
  where id=case_row.id;

  update public.order_items
  set fulfilment_status=case_row.previous_fulfilment_status,
      payout_status=case when funds_released_at is not null then 'released' when release_eligible_at is not null then 'scheduled' else 'not_ready' end
  where id=case_row.order_item_id;

  insert into public.notifications(profile_id,type,title,body,href,dedupe_key)
  values(case_row.buyer_id,'return_update','Transaction case resolved','The case was closed without a refund.','/account/cases','case-resolved:'||case_row.id::text||':buyer')
  on conflict do nothing;

  if case_row.owner_id is not null then
    insert into public.notifications(profile_id,type,title,body,href,dedupe_key)
    values(case_row.owner_id,'return_update','Transaction case resolved','The case was closed without a refund.','/dashboard/cases','case-resolved:'||case_row.id::text||':seller')
    on conflict do nothing;
  end if;

  perform private.recompute_order_status(case_row.order_id);
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_checkout_order_from_provider_event(p_order_id uuid, p_session_id text, p_event_id text, p_event_type text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  stored_session text;
  old_payment text;
begin
  if p_event_type not in ('checkout.session.expired','checkout.session.async_payment_failed') then
    raise exception 'Only terminal Stripe Checkout events may use this cancellation path.';
  end if;
  if nullif(btrim(coalesce(p_session_id,'')),'') is null then
    raise exception 'Stripe Checkout Session is required.';
  end if;
  if nullif(btrim(coalesce(p_event_id,'')),'') is null then
    raise exception 'Stripe event id is required.';
  end if;

  select provider_checkout_session_id,payment_status
  into stored_session,old_payment
  from public.orders
  where id=p_order_id
  for update;

  if not found then return false; end if;

  -- Provider terminal events must never release stock from a financially
  -- settled order. A later/stale event for another attached session also has
  -- no authority over the current reservation.
  if old_payment in ('paid','partially_refunded','refunded','disputed') then
    return false;
  end if;
  if stored_session is not null and stored_session<>p_session_id then
    return false;
  end if;

  -- If session creation succeeded at Stripe but the application had not yet
  -- persisted the returned id, the signed terminal event is sufficient
  -- provider evidence to claim that correlation. This serializes against a
  -- concurrent attach or paid-confirmation path on the same order row.
  if stored_session is null and old_payment in ('unpaid','requires_action','processing') then
    update public.orders
    set provider_checkout_session_id=p_session_id
    where id=p_order_id;
  elsif stored_session is null and old_payment<>'cancelled' then
    return false;
  end if;

  return public.cancel_checkout_order(p_order_id,p_event_id,p_event_type);
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_order_item_payout_release(p_order_item_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item record;
begin
  select oi.id,oi.payout_status,oi.release_eligible_at,oi.funds_released_at,oi.payout_rollback_required,o.payment_status
  into item
  from public.order_items oi
  join public.orders o on o.id=oi.order_id
  where oi.id=p_order_item_id
  for update of oi;

  if item.id is null then return false; end if;
  if item.payout_rollback_required then return false; end if;
  if item.payout_status='released' then return true; end if;
  if item.payout_status='releasing' then return true; end if;
  if item.payout_status<>'scheduled' then return false; end if;
  if item.funds_released_at is not null then return false; end if;
  if item.release_eligible_at is null or item.release_eligible_at>now() then return false; end if;
  if item.payment_status<>'paid' then return false; end if;
  if exists(
    select 1 from public.transaction_cases c
    where c.order_item_id=p_order_item_id
      and c.status in ('open','seller_response','under_review','return_authorized','return_shipped','returned')
  ) then return false; end if;

  update public.order_items set payout_status='releasing' where id=p_order_item_id;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.consume_ai_listing_quota()
 RETURNS TABLE(allowed boolean, remaining integer, reset_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid:=(select auth.uid());
  current_window timestamptz:=date_trunc('hour',now());
  next_count integer;
  hourly_limit constant integer:=30;
begin
  if actor is null then
    raise exception 'Authentication required.';
  end if;

  if not exists(
    select 1
    from public.sellers s
    where s.owner_id=actor
  ) then
    raise exception 'Seller profile required.';
  end if;

  insert into private.ai_listing_usage(profile_id,window_start,request_count,updated_at)
  values(actor,current_window,1,now())
  on conflict(profile_id,window_start) do update
    set request_count=private.ai_listing_usage.request_count+1,
        updated_at=now()
    where private.ai_listing_usage.request_count<hourly_limit
  returning request_count into next_count;

  if next_count is null then
    select u.request_count into next_count
    from private.ai_listing_usage u
    where u.profile_id=actor and u.window_start=current_window;

    return query
    select false,greatest(0,hourly_limit-coalesce(next_count,hourly_limit)),current_window+interval '1 hour';
    return;
  end if;

  return query
  select true,greatest(0,hourly_limit-next_count),current_window+interval '1 hour';
end;
$function$

CREATE OR REPLACE FUNCTION public.import_vehicle_catalogue_batch(p_provider text, p_variants jsonb DEFAULT '[]'::jsonb, p_years jsonb DEFAULT '[]'::jsonb, p_engines jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_variant_count integer := 0;
  v_year_count integer := 0;
  v_engine_count integer := 0;
begin
  if p_provider is null or btrim(p_provider) = '' then
    raise exception 'provider is required';
  end if;
  if jsonb_typeof(p_variants) <> 'array' or jsonb_typeof(p_years) <> 'array' or jsonb_typeof(p_engines) <> 'array' then
    raise exception 'batch payloads must be arrays';
  end if;

  insert into public.vehicle_catalogue_variants(
    provider,provider_key,make,model_family,variant,body_type,
    data_status,source_reference,source_updated_at,updated_at
  )
  select
    p_provider,x.provider_key,x.make,x.model_family,x.variant,nullif(x.body_type,''),
    'external_import'::public.vehicle_data_status,x.source_reference,x.source_updated_at,now()
  from jsonb_to_recordset(p_variants) as x(
    provider_key text,make text,model_family text,variant text,body_type text,
    source_reference text,source_updated_at date
  )
  where x.provider_key is not null and x.make is not null and x.model_family is not null
    and x.variant is not null and x.source_reference is not null
  on conflict(provider,provider_key) do update set
    make=excluded.make,model_family=excluded.model_family,variant=excluded.variant,
    body_type=excluded.body_type,data_status=excluded.data_status,
    source_reference=excluded.source_reference,source_updated_at=excluded.source_updated_at,
    updated_at=now();
  get diagnostics v_variant_count = row_count;

  insert into public.vehicle_catalogue_years(variant_id,year_first_used,source_reference)
  select v.id,y.year_first_used,y.source_reference
  from jsonb_to_recordset(p_years) as y(provider_key text,year_first_used smallint,source_reference text)
  join public.vehicle_catalogue_variants v on v.provider=p_provider and v.provider_key=y.provider_key
  where y.year_first_used between 1900 and 2100 and y.source_reference is not null
  on conflict(variant_id,year_first_used) do update set source_reference=excluded.source_reference;
  get diagnostics v_year_count = row_count;

  insert into public.vehicle_catalogue_engines(
    variant_id,fuel_type,engine_size_simple,engine_size_desc,source_reference
  )
  select v.id,e.fuel_type,e.engine_size_simple,nullif(e.engine_size_desc,''),e.source_reference
  from jsonb_to_recordset(p_engines) as e(
    provider_key text,fuel_type text,engine_size_simple integer,engine_size_desc text,source_reference text
  )
  join public.vehicle_catalogue_variants v on v.provider=p_provider and v.provider_key=e.provider_key
  where e.fuel_type is not null and e.source_reference is not null
  on conflict(variant_id,fuel_type,engine_size_simple,engine_size_desc) do update set
    source_reference=excluded.source_reference;
  get diagnostics v_engine_count = row_count;

  return jsonb_build_object('variants',v_variant_count,'years',v_year_count,'engines',v_engine_count);
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_order_item_payout_released(p_order_item_id uuid, p_transfer_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item record;
begin
  select oi.id,oi.order_id,oi.payout_status,oi.release_eligible_at,oi.funds_released_at,oi.provider_transfer_id,
         oi.payout_rollback_required,o.payment_status,o.buyer_id,p.title
  into item
  from public.order_items oi
  join public.orders o on o.id=oi.order_id
  join public.parts p on p.id=oi.part_id
  where oi.id=p_order_item_id
  for update of oi;

  if item.id is null then return false; end if;
  if item.payout_status='released' then return true; end if;

  if exists(
    select 1 from public.transaction_cases c
    where c.order_item_id=item.id
      and c.status in ('open','seller_response','under_review','return_authorized','return_shipped','returned')
  ) then
    update public.order_items
    set payout_status='blocked'
    where id=item.id and payout_status<>'released';
    return false;
  end if;

  if item.payout_rollback_required then raise exception 'Payout transfer rollback is pending.'; end if;
  if item.payout_status<>'releasing' then raise exception 'Payout release was not claimed.'; end if;
  if item.release_eligible_at is null or item.release_eligible_at>now() then raise exception 'Payout is not eligible for release.'; end if;
  if item.payment_status<>'paid' then raise exception 'Order payment is not eligible for payout.'; end if;
  if nullif(btrim(coalesce(p_transfer_id,'')),'') is null then raise exception 'Transfer id is required.'; end if;
  if item.provider_transfer_id is not null and item.provider_transfer_id<>p_transfer_id then raise exception 'Transfer id does not match the recorded payout transfer.'; end if;

  update public.order_items
  set payout_status='released',provider_transfer_id=coalesce(provider_transfer_id,p_transfer_id),
      funds_released_at=coalesce(funds_released_at,now()),fulfilment_status='completed'
  where id=item.id;

  insert into public.order_events(order_id,order_item_id,event_type,from_status,to_status,metadata)
  values(item.order_id,item.id,'seller_transfer_released',item.payout_status,'released',jsonb_build_object('transfer_id',p_transfer_id));

  insert into public.notifications(profile_id,type,title,body,href,dedupe_key)
  values(item.buyer_id,'order_update','Transaction completed',left(item.title,240),'/account/orders','transaction-complete:'||item.id::text)
  on conflict do nothing;

  perform private.recompute_order_status(item.order_id);
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.queue_orphan_case_evidence_cleanup(p_case_id uuid, p_uploader_id uuid, p_storage_path text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  participant record;
begin
  select c.id,o.buyer_id,s.owner_id
  into participant
  from public.transaction_cases c
  join public.order_items oi on oi.id=c.order_item_id
  join public.orders o on o.id=oi.order_id
  join public.sellers s on s.id=oi.seller_id
  where c.id=p_case_id;

  if participant.id is null
     or (participant.buyer_id is distinct from p_uploader_id
         and participant.owner_id is distinct from p_uploader_id) then
    raise exception 'Case evidence cleanup participant unavailable.';
  end if;

  if p_storage_path !~ (
    '^'||p_case_id::text||'/'||p_uploader_id::text||
    '/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.(jpg|png|webp)$'
  ) then
    raise exception 'Invalid orphan case evidence path.';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_storage_path,739));

  -- Registration may have succeeded in a concurrent/retried request. An
  -- attached evidence path is never Storage-delete authority.
  if exists(
    select 1 from public.transaction_case_evidence e
    where e.storage_path=p_storage_path
  ) then
    return false;
  end if;

  insert into private.case_evidence_cleanup(storage_path,case_id,uploader_id)
  values(p_storage_path,p_case_id,p_uploader_id)
  on conflict(storage_path) do nothing;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.seller_set_order_item_fulfilment(p_order_item_id uuid, p_action text, p_carrier text DEFAULT NULL::text, p_tracking_number text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid:=(select auth.uid());
  item record;
  next_status text;
begin
  if actor is null then raise exception 'Authentication required.'; end if;

  select
    oi.id,oi.order_id,oi.delivery_method,oi.fulfilment_status,
    s.owner_id,o.payment_status,o.buyer_id,p.title
  into item
  from public.order_items oi
  join public.sellers s on s.id=oi.seller_id
  join public.orders o on o.id=oi.order_id
  join public.parts p on p.id=oi.part_id
  where oi.id=p_order_item_id
  for update of oi;

  if item.id is null or (item.owner_id<>actor and not private.is_admin()) then
    raise exception 'Sale not found.';
  end if;
  if item.payment_status<>'paid' then raise exception 'The order has not been paid.'; end if;

  if p_action='preparing' then
    if item.fulfilment_status not in ('paid','preparing') then
      raise exception 'This sale can no longer be moved back to preparing.';
    end if;
    next_status:='preparing';
  elsif p_action='dispatch' then
    if item.delivery_method<>'shipping' then raise exception 'Collection orders cannot be dispatched.'; end if;
    if item.fulfilment_status not in ('paid','preparing') then
      raise exception 'This sale is not ready to be dispatched.';
    end if;
    if length(btrim(coalesce(p_tracking_number,'')))<3 then raise exception 'Add a tracking or shipment reference.'; end if;
    next_status:='dispatched';
  elsif p_action='ready_for_collection' then
    if item.delivery_method<>'collection' then raise exception 'This is not a collection order.'; end if;
    if item.fulfilment_status not in ('paid','preparing') then
      raise exception 'This sale is not ready for collection handoff.';
    end if;
    next_status:='ready_for_collection';
  else
    raise exception 'Invalid fulfilment action.';
  end if;

  update public.order_items
  set
    fulfilment_status=next_status,
    tracking_carrier=case when next_status='dispatched' then nullif(left(btrim(coalesce(p_carrier,'')),80),'') else tracking_carrier end,
    tracking_number=case when next_status='dispatched' then left(btrim(p_tracking_number),120) else tracking_number end,
    dispatched_at=case when next_status='dispatched' then coalesce(dispatched_at,now()) else dispatched_at end
  where id=p_order_item_id;

  insert into public.order_events(order_id,order_item_id,actor_profile_id,event_type,from_status,to_status,metadata)
  values(
    item.order_id,item.id,actor,'seller_fulfilment_update',item.fulfilment_status,next_status,
    jsonb_build_object(
      'carrier',nullif(left(btrim(coalesce(p_carrier,'')),80),''),
      'tracking_number',nullif(left(btrim(coalesce(p_tracking_number,'')),120),'')
    )
  );

  insert into public.notifications(profile_id,type,title,body,href,dedupe_key)
  values(
    item.buyer_id,
    case when next_status='dispatched' then 'order_dispatched' else 'order_update' end,
    case
      when next_status='dispatched' then 'Your order has been dispatched'
      when next_status='ready_for_collection' then 'Your order is ready for collection'
      else 'Your order is being prepared'
    end,
    case when next_status='ready_for_collection' then 'Your item is ready for collection.' else left(item.title,240) end,
    '/account/orders',
    'fulfilment:'||item.id::text||':'||next_status
  )
  on conflict do nothing;

  perform private.recompute_order_status(item.order_id);
  return true;
end;
$function$
